import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import React from "react";
import { renderToStaticMarkup } from "react-dom/server";
import SceneCanvas from "../features/math-tutor/components/SceneCanvas";
import { evaluate, paramValues, parseScene, resolvePoints } from "../features/math-tutor/lib/scene-eval";

// Generated by `PYTHONPATH=src python scripts/export_scene_fixtures.py` from the real backend.
const fixtures: { request: string; scene: unknown }[] = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), "tests", "fixtures", "backend-scenes.json"), "utf8"));

test("every scene the backend emits passes the client validator and renders", () => {
  assert.ok(fixtures.length >= 12);
  for (const { request, scene } of fixtures) {
    const parsed = parseScene(scene);
    assert.ok(parsed, `client rejected backend scene for: ${request}`);
    const html = renderToStaticMarkup(<SceneCanvas scene={parsed!} />);
    assert.match(html, /<canvas/, request);
  }
});

test("backend parameters become sliders and moving points evaluate on the curve", () => {
  const line = parseScene(fixtures.find(f => f.request.includes("y=kx+1"))!.scene)!;
  assert.deepEqual(line.params.map(p => p.name), ["k"]);
  const moving = parseScene(fixtures.find(f => f.request === "椭圆上的动点到焦点的距离")!.scene)!;
  assert.equal(moving.source, "model");
  for (const t of [0, 0.8, 2, 4.5]) {
    const params = paramValues(moving, { t });
    const points = resolvePoints(moving, params);
    const [px, py] = points.P!;
    assert.ok(Math.abs(px * px / 4 + py * py / 3 - 1) < 1e-9, "P stays on the ellipse");
    const readout = moving.readouts.find(r => r.label === "|PF|")!;
    const distance = evaluate(readout.expr, { vars: params, points })!;
    assert.ok(Math.abs(distance - (2 - px / 2)) < 1e-9, "focal radius |PF| = a - e·x");
  }
});
